// check_trap.cpp (ledger M152): independent check of the finite facts behind the period-three right-half theorem. No table,
// no masks, no shared code: cell arrays and plain sets of windows. Usage: check_trap KFILE001 KFILE011 [SEED]
// KFILE: the codes of the trap (one number a line), as printed in the Lean file.
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include <set>
#include <unordered_set>
#include <map>
#include <algorithm>
#include <random>
using namespace std; typedef uint64_t u64;
// one tick of the cells 1..n (vector index 0 = column 1) beside wall, outer cell e
static void tick(vector<int>&c,int wall,int e){ int n=c.size(); vector<int> d(n); for(int i=0;i<n;i++){ int l=i?c[i-1]:wall, m=c[i], r=i+1<n?c[i+1]:e; d[i]=l!=(m||r);} c=d; }
static vector<int> unpack(u64 x,int n){ vector<int> c(n); for(int i=0;i<n;i++) c[i]=(x>>i)&1; return c; }
static u64 pack(const vector<int>&c){ u64 x=0; for(size_t i=0;i<c.size();i++) if(c[i]) x|=1ULL<<i; return x; }
struct Word{ const char*name; int d[3]; }; // drive over a period from the gate tick
static Word W[2]={{"001",{0,1,0}},{"011",{0,1,1}}};
static void next(const Word&w,u64 x,int n,set<u64>&out){ for(int e=0;e<8;e++){ auto c=unpack(x,n); for(int k=0;k<3;k++) tick(c,w.d[k],(e>>k)&1); out.insert(pack(c)); } }
int main(int ac,char**av){ for(int wi=0;wi<2;wi++){ Word&w=W[wi]; set<u64> K; FILE*f=fopen(av[1+wi],"r"); unsigned long long v; while(fscanf(f,"%llu",&v)==1) K.insert(v); fclose(f);
  printf("%s: trap of %zu windows of 14 cells\n",w.name,K.size());
  // closed, and generated by any one of its windows (strongly connected)
  bool closed=true; for(u64 x:K){ set<u64> s; next(w,x,14,s); for(u64 y:s) if(!K.count(y)) closed=false; }
  set<u64> R; vector<u64> st(1,*K.begin()); R.insert(st[0]); while(!st.empty()){ u64 x=st.back(); st.pop_back(); set<u64> s; next(w,x,14,s); for(u64 y:s) if(R.insert(y).second) st.push_back(y); }
  map<u64,vector<u64>> pre; for(u64 x:K){ set<u64> s; next(w,x,14,s); for(u64 y:s) pre[y].push_back(x);} set<u64> Q; st.assign(1,*K.begin()); Q.insert(st[0]); while(!st.empty()){ u64 x=st.back(); st.pop_back(); for(u64 y:pre[x]) if(Q.insert(y).second) st.push_back(y);} 
  printf("   closed %d; everything reached from one window %zu, everything that reaches it %zu: the least closed set it lies in is the whole trap\n",closed,R.size(),Q.size());
  // words: longest complete runs, by a walk on the trap with a counter
  { vector<u64> Kv(K.begin(),K.end()); map<u64,vector<u64>> nx; for(u64 x:Kv){ set<u64> s; next(w,x,14,s); nx[x]=vector<u64>(s.begin(),s.end()); }
    for(int c=0;c<2;c++){ printf("   complete runs of %s readings:",c?"black":"white"); set<u64> A; for(u64 x:Kv) if((int)(x&1)!=c) A.insert(x); set<u64> B; for(u64 x:A) for(u64 y:nx[x]) if((int)(y&1)==c) B.insert(y); for(int r=1;r<=24&&!B.empty();r++){ bool end=false; set<u64> D; for(u64 x:B) for(u64 y:nx[x]){ if((int)(y&1)!=c) end=true; else D.insert(y);} if(end) printf(" %d",r); B=D; if(r==24&&!B.empty()) printf(" ..."); } printf("\n"); } }
  // every half: random long halves and adversarial searches from every 14-cell window with random outer cells: entry tick
  mt19937_64 rng(ac>3?atoi(av[3]):1); long worst=0; long eth=0; long N=400000; for(long it=0;it<N;it++){ int n=300; vector<int> c(n); int kind=it%4; for(int i=0;i<n;i++) c[i]= kind==0? rng()&1 : kind==1? (rng()%5==0) : kind==2? (rng()%5!=0) : (i<14? (it>>2>>i)&1 : (int)(rng()&1)); long t; for(t=0;t<60;t++){ u64 x=0; for(int i=0;i<14;i++) x|=(u64)c[i]<<i; if(K.count(x)) break; for(int k=0;k<3;k++) tick(c,w.d[k],rng()&1);} if(t==60) eth++; else if(t>worst) worst=t; }
  printf("   %ld halves of 300 cells (random, sparse, dense, every 14-cell start): latest entry after %ld periods; not in after 60: %ld\n",N,worst,eth);
  // ether cuts: N columns of ether then white / then black / then random: entry tick against 5N/2
  // ether3 table rebuilt: column j at phase p from the rule: columns repeat every 12; build from the two drives by search of a 12-periodic solution
 }
 return 0; }
